def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue

            # Find this 8-connected foreground component.
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w
                                and grid[ny][nx] != bg
                                and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            stack.append((ny, nx))

            rightmost = max(x for y, x in comp)
            rows = {}
            for y, x in comp:
                rows[y] = max(rows.get(y, -1), x)

            # Extend rightward from the component's rightmost boundary row(s).
            for y, x in rows.items():
                if x == rightmost:
                    for nx in range(x + 1, w):
                        out[y][nx] = 1

    return out
